    } catch (_) {
      return;
    }
    if (!data || !Array.isArray(data.hasMenuSection)) return;

    data.hasMenuSection.forEach(section => {
      const sectionName = section.name ? cleanText(section.name) : null;
      if (!Array.isArray(section.hasMenuItem)) return;

      section.hasMenuItem.forEach(item => {
        const name = cleanText(item.name ?? '');
        if (!name) return;

        const description = item.description
          ? cleanText(item.description)
          : null;

        let price = null;
