        }

        const key = `${sectionName ?? ''}|${name}|${description ?? ''}|${price ?? ''}`;
        if (seen.has(key)) return;
        seen.add(key);

        items.push({
          section: sectionName,
          name,
          description,
          price
        });
      });
    });
  });

  return items;
}
